const visual = {
  prepare: function (input) {
    var labels = [];
    for (var i = -5; i <= 5; i++) {
      labels.push({ kind: 'text', payload: String(i) });
    }
    return labels;
  },
  render: function (input, metrics) {
    var w = input.viewport.widthDu;
    var h = input.viewport.heightDu;
    var margin = Math.min(Math.max(18, w * 0.08), w * 0.25);
    var left = margin;
    var right = w - margin;
    var span = right - left;
    var y = h * 0.46;
    var tickLen = Math.max(6, Math.min(16, h * 0.045));
    var labelGap = Math.max(4, Math.min(14, h * 0.03));
    var axisCommands = [['M', left, y], ['L', right, y]];
    var tickCommands = [];
    var xs = [];
    for (var i = 0; i < 11; i++) {
      var x = left + span * (i / 10);
      xs.push(x);
      tickCommands.push(['M', x, y - tickLen / 2]);
      tickCommands.push(['L', x, y + tickLen / 2]);
    }
    var children = [
      { type: 'path', pathId: 'axis', fill: '#26354A', stroke: { width: 2 } },
      { type: 'path', pathId: 'ticks', fill: '#26354A', stroke: { width: 2 } }
    ];
    for (var j = 0; j < 11; j++) {
      children.push({
        type: 'label',
        contentId: metrics[j].contentId,
        anchor: { x: xs[j], y: y + tickLen / 2 + labelGap },
        hAlign: 'center',
        vAlign: 'top',
        color: '#26354A'
      });
    }
    return {
      schemaVersion: 1,
      sceneId: 'source-axis-5-to-5',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: [
        { id: 'axis', commands: axisCommands },
        { id: 'ticks', commands: tickCommands }
      ],
      root: { type: 'group', children: children }
    };
  }
};
